 	int gpu_delta;
 	u8 mode;
-	u8 pwm;
+	u8 pwm[2];
 	struct delayed_work keep_alive_dwork;
 };
 
@@ -822,12 +822,18 @@ static int hp_wmi_fan_speed_set(struct hp_wmi_hwmon_priv *priv, u8 speed)
 	fan_speed[GPU_FAN] = speed;
 
