 fs/crypto/fscrypt_private.h |  3 +-
 fs/crypto/keysetup.c        | 59 +++++++++++++++++++++++++---------
 include/linux/fscrypt.h     | 28 +++++++++++++++++
 4 files changed, 138 insertions(+), 15 deletions(-)

