  * fscrypt_encrypt_block_inplace() - Encrypt a filesystem block in-place
  * @inode:     The inode to which this block belongs
@@ -282,6 +320,31 @@ int fscrypt_decrypt_pagecache_blocks(struct folio *folio, size_t len,
