+int fscrypt_decrypt_data_unit_inplace(const struct inode *inode,
+				      struct page *page, unsigned int len,
+				      unsigned int offs, u64 index)
+{
+	const struct fscrypt_inode_info *ci = fscrypt_get_inode_info_raw(inode);
